jsxGraph.script:
board.suspendUpdate();
var pA = board.create('point', [1, 2], {size: 3, color: 'black', name: 'A(1, 2)', withLabel: true, label: {autoPosition: false, offset: [-15, 10]}});
var pB = board.create('point', [5, 8], {size: 3, color: 'black', name: 'B(5, 8)', withLabel: true, label: {autoPosition: false, offset: [10, 10]}});
var pC = board.create('point', [7, 0], {size: 3, color: 'black', name: 'C(7, 0)', withLabel: true, label: {autoPosition: false, offset: [10, -10]}});
board.create('polygon', [pA, pB, pC], {fillColor: 'none', borders: {strokeColor: 'black', strokeWidth: 1.5}});
board.unsuspendUpdate();
